import{_ as s,o as i,c as t,a5 as n}from"./chunks/framework.C1a7WKBV.js";const c=JSON.parse('{"title":"Agent 评测与可观测性","description":"通过轨迹评测、故障分类、Span 设计与线上指标，系统判断 Agent 的可靠性、成本和安全性。","frontmatter":{"title":"Agent 评测与可观测性","description":"通过轨迹评测、故障分类、Span 设计与线上指标，系统判断 Agent 的可靠性、成本和安全性。"},"headers":[],"relativePath":"agents/evaluation-and-observability.md","filePath":"agents/evaluation-and-observability.md","lastUpdated":1788838685000}'),e={name:"agents/evaluation-and-observability.md"};function l(h,a,p,d,r,o){return i(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="agent-评测与可观测性" tabindex="-1">Agent 评测与可观测性 <a class="header-anchor" href="#agent-评测与可观测性" aria-label="Permalink to &quot;Agent 评测与可观测性&quot;">​</a></h1><p>普通生成任务常只评价最终文本；Agent 还必须评价过程。同一个正确结果，可能来自一次精准调用，也可能来自二十次碰撞、越权尝试后侥幸成功。只看终点会奖励危险和昂贵的轨迹。</p><h2 id="_1-定义任务成功" tabindex="-1">1. 定义任务成功 <a class="header-anchor" href="#_1-定义任务成功" aria-label="Permalink to &quot;1. 定义任务成功&quot;">​</a></h2><p>每个任务样本至少包含：初始环境、目标、可用工具、验收器、禁止动作和预算。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;repo-fix-017&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;goal&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;修复日期解析回归&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;initial_snapshot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fixture:v12&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;acceptance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;targeted_tests_pass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;typecheck_pass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;no_unrelated_diff&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;forbidden&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;disable_test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;network_access&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;budget&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_steps&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_cost&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>验收尽量在隔离环境中由代码执行。模型自己说“测试已通过”不是测试证据。</p><h2 id="_2-结果、轨迹与效率三层指标" tabindex="-1">2. 结果、轨迹与效率三层指标 <a class="header-anchor" href="#_2-结果、轨迹与效率三层指标" aria-label="Permalink to &quot;2. 结果、轨迹与效率三层指标&quot;">​</a></h2><h3 id="_2-1-结果指标" tabindex="-1">2.1 结果指标 <a class="header-anchor" href="#_2-1-结果指标" aria-label="Permalink to &quot;2.1 结果指标&quot;">​</a></h3><p>任务成功率、部分完成率、验收项通过率、安全违规率、人工接管后的成功率。</p><h3 id="_2-2-轨迹指标" tabindex="-1">2.2 轨迹指标 <a class="header-anchor" href="#_2-2-轨迹指标" aria-label="Permalink to &quot;2.2 轨迹指标&quot;">​</a></h3><p>工具选择正确率、参数有效率、重复动作率、无效重规划次数、危险动作拦截率、关键结论证据覆盖率。轨迹不要求与专家路径完全相同，但必须满足不变量。</p><h3 id="_2-3-效率指标" tabindex="-1">2.3 效率指标 <a class="header-anchor" href="#_2-3-效率指标" aria-label="Permalink to &quot;2.3 效率指标&quot;">​</a></h3><p>每成功任务的 Token、费用、步骤数、P50/P95 时长，以及失败任务浪费的费用。用“每成功任务成本”比“每次调用均价”更能反映系统价值。</p><h2 id="_3-事件与-span-设计" tabindex="-1">3. 事件与 Span 设计 <a class="header-anchor" href="#_3-事件与-span-设计" aria-label="Permalink to &quot;3. 事件与 Span 设计&quot;">​</a></h2><p>一次 Run 对应一条 Trace，每个模型、检索、工具、审批和校验动作对应 Span：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run: repo-fix-017</span></span>
<span class="line"><span>├─ context.build</span></span>
<span class="line"><span>├─ model.choose_action</span></span>
<span class="line"><span>├─ tool.read_file</span></span>
<span class="line"><span>├─ model.choose_action</span></span>
<span class="line"><span>├─ tool.apply_patch</span></span>
<span class="line"><span>├─ tool.run_tests</span></span>
<span class="line"><span>├─ verifier.diff_scope</span></span>
<span class="line"><span>└─ run.finish</span></span></code></pre></div><p>每个 Span 记录：<code>run_id</code>、<code>step</code>、父节点、开始结束时间、组件版本、输入输出摘要、Token/费用、状态、错误码和重试次数。提示词正文与工具结果可能含秘密，应分级存储并设置保留周期，不能为了可观测性制造新的泄露面。</p><h2 id="_4-建立稳定的故障分类" tabindex="-1">4. 建立稳定的故障分类 <a class="header-anchor" href="#_4-建立稳定的故障分类" aria-label="Permalink to &quot;4. 建立稳定的故障分类&quot;">​</a></h2><p>建议从以下顶层开始：</p><table tabindex="0"><thead><tr><th>类别</th><th>表现</th><th>责任层</th></tr></thead><tbody><tr><td>意图错误</td><td>理解错目标或验收</td><td>上下文 / 模型</td></tr><tr><td>规划错误</td><td>步骤缺失、顺序错误、循环</td><td>模型 / 状态机</td></tr><tr><td>工具选择错误</td><td>选错工具或没调用必要工具</td><td>工具描述 / 模型</td></tr><tr><td>参数错误</td><td>Schema 或业务参数非法</td><td>工具接口 / 模型</td></tr><tr><td>执行错误</td><td>超时、外部服务失败</td><td>运行时 / 依赖</td></tr><tr><td>观察错误</td><td>忽略或误读工具结果</td><td>上下文 / 模型</td></tr><tr><td>验收错误</td><td>错把未完成当完成</td><td>验收器 / 模型</td></tr><tr><td>策略违规</td><td>越权、未审批写入</td><td>权限 / 运行时</td></tr></tbody></table><p>稳定错误码能回答“本周成功率下降是模型选择变差，还是外部工具超时”，避免所有失败都归因于模型。</p><h2 id="_5-离线评测方法" tabindex="-1">5. 离线评测方法 <a class="header-anchor" href="#_5-离线评测方法" aria-label="Permalink to &quot;5. 离线评测方法&quot;">​</a></h2><h3 id="_5-1-可重放环境" tabindex="-1">5.1 可重放环境 <a class="header-anchor" href="#_5-1-可重放环境" aria-label="Permalink to &quot;5.1 可重放环境&quot;">​</a></h3><p>代码任务使用固定仓库快照和容器；浏览器任务使用测试站点与固定数据；业务任务用沙箱 API。外部时间、随机数据和真实账户会让结果不可复现。</p><h3 id="_5-2-多次运行看分布" tabindex="-1">5.2 多次运行看分布 <a class="header-anchor" href="#_5-2-多次运行看分布" aria-label="Permalink to &quot;5.2 多次运行看分布&quot;">​</a></h3><p>Agent 路径具有随机性。关键样本至少运行多次，报告成功率分布与尾部成本，而不是只展示最好的一次。模型或提示词版本比较时使用相同快照和预算。</p><h3 id="_5-3-故障注入" tabindex="-1">5.3 故障注入 <a class="header-anchor" href="#_5-3-故障注入" aria-label="Permalink to &quot;5.3 故障注入&quot;">​</a></h3><p>主动制造工具超时、429、返回空列表、部分写入、格式变化和权限拒绝，验证 Agent 是否分类错误、遵守预算并安全恢复。顺利路径通过不代表系统可靠。</p><h2 id="_6-轨迹评分避免两个极端" tabindex="-1">6. 轨迹评分避免两个极端 <a class="header-anchor" href="#_6-轨迹评分避免两个极端" aria-label="Permalink to &quot;6. 轨迹评分避免两个极端&quot;">​</a></h2><p>不能要求 Agent 完全复制标准轨迹，因为可能存在多条正确路径；也不能只看最终状态。更合适的是定义轨迹不变量：</p><ul><li>写入前必须读取当前版本；</li><li>高风险动作前必须有有效审批；</li><li>测试失败后不能宣称成功；</li><li>不得访问范围外资源；</li><li>相同失败不得无上限重试。</li></ul><p>其余步骤允许自由，只对成本与冗余施加软评分。</p><h2 id="_7-线上仪表盘与告警" tabindex="-1">7. 线上仪表盘与告警 <a class="header-anchor" href="#_7-线上仪表盘与告警" aria-label="Permalink to &quot;7. 线上仪表盘与告警&quot;">​</a></h2><p>至少分任务类型展示：成功率、人工接管率、P95 时长、每成功任务成本、工具错误率、预算耗尽率、安全拦截和用户撤销率。按模型、提示版本、工具版本、租户和任务难度切片。</p><p>告警应对应可行动问题：某工具 <code>PERMISSION_DENIED</code> 激增、P95 步数翻倍、验收失败但 Agent 报成功、单任务费用越过硬上限。单纯 Token 总量上升可能只是流量增长，信息不足。</p><h2 id="_8-从一次失败到永久改进" tabindex="-1">8. 从一次失败到永久改进 <a class="header-anchor" href="#_8-从一次失败到永久改进" aria-label="Permalink to &quot;8. 从一次失败到永久改进&quot;">​</a></h2><ol><li>用 <code>run_id</code> 重建时间线；</li><li>找到第一个偏离正确路径的 Span，而不是只看最后报错；</li><li>判断属于数据、上下文、模型、工具、运行时还是验收；</li><li>把脱敏后的案例加入对应组件评测；</li><li>做最小修改并运行全量回归；</li><li>灰度发布，观察同类错误是否下降。</li></ol><p>没有进入评测集的事故，很容易在下一次模型、提示词或工具升级后复发。</p>`,38)])])}const u=s(e,[["render",l]]);export{c as __pageData,u as default};
